package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FilteringParserDelegate#nextToken
 */
public class FilteringParserDelegate_nextToken_TriageGen2Test {

    private JsonParser mockDelegate;
    private TokenFilter mockFilter;
    private TokenFilterContext mockHeadContext;
    private TokenFilterContext mockExposedContext;

    @Before
    public void setUp() {
        mockDelegate = mock(JsonParser.class);
        mockFilter = mock(TokenFilter.class);
        mockHeadContext = mock(TokenFilterContext.class);
        mockExposedContext = mock(TokenFilterContext.class);
    }

    // Helper to instantiate the delegate and inject protected/private fields via reflection
    // since the class is designed to be extended or used via delegate patterns.
    private FilteringParserDelegate createDelegate(boolean includePath, boolean allowMultipleMatches) throws Exception {
        // Using a subclass to allow instantiation of the protected class if necessary, 
        // but here we assume we are testing the logic of the delegate.
        FilteringParserDelegate delegate = new FilteringParserDelegate(mockDelegate, mockFilter, includePath, allowMultipleMatches) {
            @Override
            protected JsonToken _nextToken2() throws IOException {
                return null; // Stub to prevent infinite recursion in tests
            }
            @Override
            protected JsonToken _nextTokenWithBuffering(TokenFilterContext ctxt) throws IOException {
                return null;
            }
        };
        return delegate;
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private void setCurrToken(FilteringParserDelegate delegate, JsonToken token) throws Exception {
        setField(delegate, "_currToken", token);
    }

    @Test
    public void testNextToken_NullExposedContext_EndStructReturnsNull() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        setField(delegate, "_exposedContext", null);
        setField(delegate, "_includePath", false);

        JsonToken endToken = mock(JsonToken.class);
        when(endToken.isStructEnd()).thenReturn(true);
        setCurrToken(delegate, endToken);

        when(mockHeadContext.isStartHandled()).thenReturn(true);
        setField(delegate, "_headContext", mockHeadContext);

        assertNull(delegate.nextToken());
    }

    @Test
    public void testNextToken_NullExposedContext_ScalarValueReturnsNull() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        setField(delegate, "_exposedContext", null);
        setField(delegate, "_includePath", false);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);

        JsonToken scalarToken = mock(JsonToken.class);
        when(scalarToken.isScalarValue()).thenReturn(true);
        setCurrToken(delegate, scalarToken);

        when(mockHeadContext.isStartHandled()).thenReturn(false);
        setField(delegate, "_headContext", mockHeadContext);

        assertNull(delegate.nextToken());
    }

    @Test
    public void testNextToken_BufferedContext_ReturnsNextToken() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        setField(delegate, "_exposedContext", mockExposedContext);
        setField(delegate, "_headContext", mockHeadContext);

        JsonToken nextT = JsonToken.FIELD_NAME;
        when(mockExposedContext.nextTokenToRead()).thenReturn(nextT);

        assertEquals(nextT, delegate.nextToken());
    }

    @Test
    public void testNextToken_BufferedContext_ChainBrokenThrowsException() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        setField(delegate, "_exposedContext", mockExposedContext);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockExposedContext.nextTokenToRead()).thenReturn(null);
        when(mockHeadContext.findChildOf(mockExposedContext)).thenReturn(null);

        try {
            delegate.nextToken();
            fail("Should have thrown exception");
        } catch (Exception e) {
            assertTrue(e.getMessage().contains("chain of filtered context broken"));
        }
    }

    @Test
    public void testNextToken_BufferedContext_HeadContextInArray() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        setField(delegate, "_exposedContext", mockHeadContext);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.nextTokenToRead()).thenReturn(null);
        when(mockHeadContext.inArray()).thenReturn(true);
        when(mockDelegate.getCurrentToken()).thenReturn(JsonToken.END_ARRAY);

        assertEquals(JsonToken.END_ARRAY, delegate.nextToken());
    }

    @Test
    public void testNextToken_ReadMore_StartArray_IncludeAll() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.createChildArrayContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockHeadContext);

        assertEquals(JsonToken.START_ARRAY, delegate.nextToken());
        verify(mockHeadContext).createChildArrayContext(TokenFilter.INCLUDE_ALL, true);
    }

    @Test
    public void testNextToken_ReadMore_StartArray_SkipChildren() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        setField(delegate, "_itemFilter", null); // f == null case
        setField(delegate, "_headContext", mockHeadContext);

        assertNull(delegate.nextToken());
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testNextToken_ReadMore_StartObject_FilterCheck() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_OBJECT);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.createChildObjectContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockHeadContext);

        assertEquals(JsonToken.START_OBJECT, delegate.nextToken());
    }

    @Test
    public void testNextToken_EndArray_ReturnsToken() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.END_ARRAY);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.isStartHandled()).thenReturn(true);
        when(mockHeadContext.getFilter()).thenReturn(TokenFilter.INCLUDE_ALL);
        when(mockHeadContext.getParent()).thenReturn(mockHeadContext);

        assertEquals(JsonToken.END_ARRAY, delegate.nextToken());
    }

    @Test
    public void testNextToken_FieldName_IncludeAll() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("testField");
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.setFieldName("testField")).thenReturn(TokenFilter.INCLUDE_ALL);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.FIELD_NAME, delegate.nextToken());
    }

    @Test
    public void testNextToken_FieldName_PropertyNotIncluded() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("testField");
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.setFieldName("testField")).thenReturn(mockFilter);
        when(mockFilter.includeProperty("testField")).thenReturn(null);

        assertNull(delegate.nextToken());
        verify(mockDelegate).nextToken();
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testNextToken_ScalarValue_IncludeAll() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        setField(delegate, "_itemFilter", TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.VALUE_STRING, delegate.nextToken());
    }

    @Test
    public void testNextToken_ScalarValue_CheckValue() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        setField(delegate, "_itemFilter", mockFilter);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.checkValue(mockFilter)).thenReturn(TokenFilter.INCLUDE_ALL);

        assertEquals(JsonToken.VALUE_NUMBER_INT, delegate.nextToken());
    }

    @Test
    public void testNextToken_ScalarValue_IncludeValue() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_TRUE);
        setField(delegate, "_itemFilter", mockFilter);
        setField(delegate, "_headContext", mockHeadContext);

        when(mockHeadContext.checkValue(mockFilter)).thenReturn(mockFilter);
        when(mockFilter.includeValue(mockDelegate)).thenReturn(true);

        assertEquals(JsonToken.VALUE_TRUE, delegate.nextToken());
    }

    @Test
    public void testNextToken_DelegateReturnsNull() throws Exception {
        FilteringParserDelegate delegate = createDelegate(false, true);
        when(mockDelegate.nextToken()).thenReturn(null);

        assertNull(delegate.nextToken());
    }
}
